from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from copy import deepcopy
import hashlib, json, re, shutil
from docx import Document
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Inches

ROOT=Path(r'C:\Users\Ult_Orange\Desktop\handvox')
FOLDER=ROOT/'ผลลัพธ์เอกสาร'
SRC=FOLDER/'บทที่ 2.docx'
OUT=FOLDER/'บทที่ 2_ตรวจแก้เนื้อหาและอ้างอิง_2569-09-16.docx'
BACKUP=FOLDER/'สำรอง_บทที่ 2_ก่อนตรวจแก้_2569-09-16.docx'
if not BACKUP.exists(): shutil.copy2(SRC,BACKUP)
assert hashlib.sha256(SRC.read_bytes()).digest()==hashlib.sha256(BACKUP.read_bytes()).digest()
d=Document(SRC)
p=list(d.paragraphs)
body_template=deepcopy(p[15]._p)
h1_template=deepcopy(p[14]._p)
h2_template=deepcopy(p[16]._p)

def put(par,text):
    rpr=deepcopy(par.runs[0]._r.rPr) if par.runs and par.runs[0]._r.rPr is not None else None
    for child in list(par._p):
        if child.tag!=qn('w:pPr'):par._p.remove(child)
    r=par.add_run(text)
    if rpr is not None:r._r.insert(0,rpr)

