def table_rows(t,rows):
    while len(t.rows)<len(rows):
        t._tbl.append(deepcopy(t.rows[-1]._tr))
    while len(t.rows)>len(rows):t._tbl.remove(t.rows[-1]._tr)
    for row,vals in zip(t.rows,rows):
        for cell,txt in zip(row.cells,vals):
            put(cell.paragraphs[0],txt)
            for par in cell.paragraphs[1:]:par._p.getparent().remove(par._p)
        # prevent row splitting, but do not force fixed heights
        trpr=row._tr.get_or_add_trPr()
        if trpr.find(qn('w:cantSplit')) is None:trpr.append(OxmlElement('w:cantSplit'))
    header=t.rows[0]._tr.get_or_add_trPr()
    if header.find(qn('w:tblHeader')) is None:header.append(OxmlElement('w:tblHeader'))

