def append(text,kind='body'):
    template={'body':body_template,'h1':h1_template,'h2':h2_template}[kind]
    el=deepcopy(template)
    d._element.body.insert(len(d._element.body)-1,el)
    from docx.text.paragraph import Paragraph
    par=Paragraph(el,d._body);put(par,text)
    if kind=='body':par._p.get_or_add_pPr().get_or_add_jc().set(qn('w:val'),'thaiDistribute')
    return par

