# Mark Thai runs as complex-script text.  Word then uses its Thai dictionary line
# breaker without artificial spaces or manual line breaks.  `w:szCs` is explicit
# because Word otherwise falls back to the complex-script default size.
def inherited_font_value(run, par, name):
    value=getattr(run.font,name)
    if value is not None:return value
    style=par.style
    seen=set()
    while style is not None and style.style_id not in seen:
        seen.add(style.style_id)
        value=getattr(style.font,name)
        if value is not None:return value
        style=style.base_style
    return None

def set_onoff(props, tag, value):
    node=props.find(qn(tag))
    if node is None:
        node=OxmlElement(tag)
        props.append(node)
    node.set(qn('w:val'),'1' if value else '0')

all_paragraphs=list(d.paragraphs)+[p for t in d.tables for row in t.rows for c in row.cells for p in c.paragraphs]
for par in all_paragraphs:
    ppr=par._p.get_or_add_pPr()
    for node in ppr.findall(qn('w:wordWrap')):ppr.remove(node)
    wrap=OxmlElement('w:wordWrap')
    wrap.set(qn('w:val'),'on')
    ppr.append(wrap)
    for run in par.runs:
        if not any('\u0E00' <= char <= '\u0E7F' for char in run.text):continue
        props=run._r.get_or_add_rPr()
        lang=props.find(qn('w:lang'))
        if lang is None:lang=OxmlElement('w:lang');props.append(lang)
        for attr in ['val','eastAsia','bidi']:lang.set(qn('w:'+attr),'th-TH')
        if props.find(qn('w:cs')) is None:props.append(OxmlElement('w:cs'))
        size=inherited_font_value(run,par,'size')
        if size is not None:
            szcs=props.find(qn('w:szCs'))
            if szcs is None:
                szcs=OxmlElement('w:szCs')
                props.append(szcs)
            szcs.set(qn('w:val'),str(round(size.pt*2)))
        bold=inherited_font_value(run,par,'bold')
        italic=inherited_font_value(run,par,'italic')
        set_onoff(props,'w:bCs',bool(bold))
        set_onoff(props,'w:iCs',bool(italic))
